import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E3%83%9E%E3%82%B0%E3%83%8A%E3%82%B9%E3%82%B1%E3%83%83%E3%83%81.html","title":"マグナスケッチ","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.92,"words":275},"filePathRelative":"マグナスケッチ.md"}`),a={name:`マグナスケッチ.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="マグナスケッチ" tabindex="-1"><a class="header-anchor" href="#マグナスケッチ"><span>マグナスケッチ</span></a></h1><p><a href="./自作アプリ.html">自作アプリ</a></p><p><a href="./BOOX.html">BOOX</a>用の電子メモパッドみたいな描くだけアプリ。</p><ul><li><a href="https://github.com/karino2/MagnaSketch" target="_blank" rel="noopener noreferrer">karino2/MagnaSketch: Toy magnetic drawing board like app for BOOX.</a><ul><li><a href="https://github.com/karino2/SSaverSetter" target="_blank" rel="noopener noreferrer">karino2/SSaverSetter: Receive image intent and set to ScreenSaver, for BOOX only.</a> これでスクリーンセーバーにしてる。</li></ul></li><li><a href="https://www.youtube.com/watch?v=9QXh114BIaM" target="_blank" rel="noopener noreferrer">自作アプリ紹介 マグナスケッチ - YouTube</a></li></ul><p>作った時は一発ネタかな、と思ったが、思ったよりも自分で使っているアプリ。</p><h2 id="毎朝しばらく書き散らかすのが楽しい" tabindex="-1"><a class="header-anchor" href="#毎朝しばらく書き散らかすのが楽しい"><span>毎朝しばらく書き散らかすのが楽しい</span></a></h2><p>朝、ソファでコーヒーを飲みながら、なんとはなしに思いついた事を書いては消して、とやっているのが楽しい。 この楽しさはなんなのか、いろいろ考えている。</p><p>ページの余白を前に考えている時間が楽しい。 これは考える、という事を軽く強制するツールで、そこが良い。</p><p>考えている時間、というのは、豊かな日常というか、いい感じの朝が過せる。</p><h2 id="_1枚に考えをまとめる良さ" tabindex="-1"><a class="header-anchor" href="#_1枚に考えをまとめる良さ"><span>1枚に考えをまとめる良さ</span></a></h2><p>紙1枚に考えを書き出す、というのが、創造的な思考(というと大袈裟だが)に良いのではないか。</p><p>全体を把握できる程度の短かさ、少し考えないと埋められない程度の長さ、 すぐに最初から全部書き直せる程度の短かさ。</p><p>すぐに終るのでやる気が起きるゲームみたいだ。 やる気が起きるくらいにはすぐ終わるが、少し考える必要があるくらいの長さなのがいい気がする。</p><h2 id="書く事で考える、に特化している" tabindex="-1"><a class="header-anchor" href="#書く事で考える、に特化している"><span>書く事で考える、に特化している</span></a></h2><p>書く、というのを、考えるためのツールとして使う事に特化していて、それが他に無い楽しさをうんでいる。 残せないが故に考える以外の余計な事を気にしなくていい。</p><p>考える事しか出来無いので、考える事に集中出来る。 自由に思考をさまよわせる楽しさがある。</p><h2 id="同じ事を2度書くメリット" tabindex="-1"><a class="header-anchor" href="#同じ事を2度書くメリット"><span>同じ事を2度書くメリット</span></a></h2><p>消すのが全消ししか無いので、ちょっと書き損じたりすると全部書き直す事になる。 同じ事をもう一度書くのは面倒もあるのだが、 作り直す良さもある。</p><p>それは一度つくった事があるプログラムをもう一度作るのに似た良さがある。 二回目は、一回目に作って｢もっとこうした方が良かったなぁ｣という所を直せる良さがある。</p><p>同じ事を二度書くと、二度目の方が整理されているし、より深く考えられる。</p><p>考える時間もトータルで倍、とまではいかないが、それくらいのオーダーで増える。</p><p>そういう訳で、すぐに書き直すのは悪くない。</p><h2 id="消すのが気分が良い" tabindex="-1"><a class="header-anchor" href="#消すのが気分が良い"><span>消すのが気分が良い</span></a></h2><p>なんか｢ぱっ｣と全部消えるのが、気分が良い。この消すのを楽しむために書く、みたいな部分がある。 意味の無い事を書いて、ただ消す。楽しい。</p><p>この楽しさを味わうために書くのが促進されて、それが考えるのを促進する。</p>`,25)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};